

create or replace view LOG_PERSONNEL_COM as
SELECT "ID","PERMIS_CONDUIRE","CHEMIN_PERMIS","REMARQUE","ID_PERS","NOM","PRENOM","DATE_NAISSANCE","SEXE","NUMERO_CIN","DATE_CIN","DATE_DUPL_CIN","NATIONALITE","ADRESSE","FOKOTANY","ACTE_NAISSANCE","DIRECTION","SERVICE","REFUSER","IDSUP","IDHIERARCHIE","CHEMINIMAGE","IDCIVILITE","MERE","PERE" FROM log_personnel WHERE service = 'SERV0002';

update CLIENT set IDTYPECLIENT='TYPE009', IDTARIFICATION='TYPE009' where id='CLI000576';

